import itertools
from games import sub, nim, wythoff

def brute(N):
    win=[[False]*(N+1) for _ in range(N+1)]
    for a in range(N+1):
        for b in range(N+1):
            if a==0 and b==0: continue
            w=False
            for k in range(1,a+1):
                if not win[a-k][b]:w=True
            for k in range(1,b+1):
                if not win[a][b-k]:w=True
            for k in range(1,min(a,b)+1):
                if not win[a-k][b-k]:w=True
            win[a][b]=w
    return win
