import random
def life_step(g,H,W):
    n=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            cnt=0
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    if dr==0 and dc==0:continue
                    rr,cc=r+dr,c+dc
                    if 0<=rr<H and 0<=cc<W and g[rr][cc]=='#':cnt+=1
            alive=g[r][c]=='#'
            n[r][c]='#' if (alive and cnt in(2,3)) or (not alive and cnt==3) else '.'
    return n
